llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Cilomilast absolute oral bioavailability was 96% (range 92–102%) in healthy humans after a 10 mg oral solution versus IV infusion, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Irbesartan absolute oral bioavailability is about 70% after oral administration in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Vernakalant absolute oral bioavailability was 71 ± 21% in fasted healthy volunteers after 5 mg/kg p.o. versus IV, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Urapidil absolute oral bioavailability was 78% from a 30 mg oral solution in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In cirrhotic liver patients, meptazinol absolute oral bioavailability was 27.9 ± 5.3% after 200 mg p.o. versus 25 mg i.v., directly matching the cirrhosis condition and exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "In a healthy male volunteer, meptazinol absolute oral bioavailability was 8.81% after 200 mg oral versus IV, indicating low F in the non-cirrhotic state; this is outweighed by the cirrhosis-matched record and the overall high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High predicted: most high-transfer analogues show absolute oral bioavailability well above 20% (cilomilast 96%, irbesartan 60–80%, vernakalant 58–71%, urapidil 72–78%), and the only cirrhosis-matched record (meptazinol) gives F=27.9±5.3%, still above threshold. Low healthy-state meptazinol values are outweighed by condition mismatch and the overall high-F pattern.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No query-specific cirrhosis pharmacokinetic data.",
    "The query's cyclic disulfone moiety is not directly represented among the evidence molecules.",
    "Healthy-state low-F records (meptazinol, imipramine with food) may not translate to the cirrhotic condition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

